func TestFilesService_Upload(t *testing.T) {
	t.Parallel()

	fileContent := []byte("file-content")

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		if got := r.Header.Get("X-Test"); got != "upload" {
			t.Fatalf("unexpected header X-Test: %q", got)
		}

		mediaType, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
		if err != nil {
			t.Fatalf("parse content type: %v", err)
		}
		if mediaType != "multipart/form-data" {
			t.Fatalf("unexpected media type: %s", mediaType)
		}

		form, err := multipart.NewReader(r.Body, params["boundary"]).ReadForm(1 << 20)
		if err != nil {
			t.Fatalf("read form: %v", err)
		}

		parts := form.File["file"]
		if len(parts) != 1 {
			t.Fatalf("expected 1 file part, got %d", len(parts))
		}
		if parts[0].Filename != "report.pdf" {
			t.Fatalf("unexpected filename: %q", parts[0].Filename)
		}
		part, err := parts[0].Open()
		if err != nil {
			t.Fatalf("open part: %v", err)
		}
		payload, err := io.ReadAll(part)
		_ = part.Close()
		if err != nil {
			t.Fatalf("read part: %v", err)
		}
		if !bytes.Equal(payload, fileContent) {
			t.Fatalf("unexpected payload: %q", payload)
		}

		if got := form.Value["deal_id"]; len(got) != 1 || got[0] != "7" {
			t.Fatalf("unexpected deal_id: %#v", got)
		}
		if got := form.Value["person_id"]; len(got) != 1 || got[0] != "8" {
			t.Fatalf("unexpected person_id: %#v", got)
		}
		if got := form.Value["org_id"]; len(got) != 1 || got[0] != "9" {
			t.Fatalf("unexpected org_id: %#v", got)
		}
		if got := form.Value["product_id"]; len(got) != 1 || got[0] != "10" {
			t.Fatalf("unexpected product_id: %#v", got)
		}
		if got := form.Value["activity_id"]; len(got) != 1 || got[0] != "11" {
			t.Fatalf("unexpected activity_id: %#v", got)
		}
		if got := form.Value["lead_id"]; len(got) != 1 || got[0] != "b4a5c0d0-0e10-11eb-879b-05d71fb426ec" {
			t.Fatalf("unexpected lead_id: %#v", got)
		}
		if got := form.Value["project_id"]; len(got) != 1 || got[0] != "13" {
			t.Fatalf("unexpected project_id: %#v", got)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"report.pdf"}}`))
	})

	file, err := client.Files.Upload(
		context.Background(),
		"report.pdf",
		bytes.NewReader(fileContent),
		WithFileDealID(7),
		WithFilePersonID(8),
		WithFileOrganizationID(9),
		WithFileProductID(10),
		WithFileActivityID(11),
		WithFileLeadID("b4a5c0d0-0e10-11eb-879b-05d71fb426ec"),
		WithFileProjectID(13),
		WithFilesRequestOptions(pipedrive.WithHeader("X-Test", "upload")),
	)
	if err != nil {
		t.Fatalf("Upload error: %v", err)
	}
	if file.ID != 12 || file.Name != "report.pdf" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

func TestFilesService_Upload_RetriesOnRateLimit(t *testing.T) {
	t.Parallel()

	var calls int
	var bodies [][]byte
	client := newTestClientWithConfig(t, pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{MaxAttempts: 3, BaseDelay: time.Millisecond, MaxDelay: time.Millisecond},
	}, func(w http.ResponseWriter, r *http.Request) {
		payload, err := io.ReadAll(r.Body)
		if err != nil {
			t.Fatalf("read request body: %v", err)
		}
		bodies = append(bodies, payload)
		calls++
		if calls == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"message":"rate limited"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"report.pdf"}}`))
	})

	file, err := client.Files.Upload(context.Background(), "report.pdf", strings.NewReader("file-content"))
	if err != nil {
		t.Fatalf("Upload error: %v", err)
	}
	if file.ID != 12 {
		t.Fatalf("unexpected file: %#v", file)
	}
	if calls != 2 {
		t.Fatalf("expected 2 calls, got %d", calls)
	}
	if len(bodies[0]) == 0 {
		t.Fatalf("expected multipart body on first attempt")
	}
	if !bytes.Equal(bodies[0], bodies[1]) {
		t.Fatalf("retried body differs from original")
	}
}

func TestFilesService_Upload_Validation(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		t.Fatalf("unexpected request: %s %s", r.Method, r.URL.Path)
	})

	if _, err := client.Files.Upload(context.Background(), "", strings.NewReader("x")); err == nil {
		t.Fatalf("expected file name error")
	}
	if _, err := client.Files.Upload(context.Background(), "report.pdf", nil); err == nil {
		t.Fatalf("expected content error")
	}
	if _, err := client.Files.Upload(context.Background(), "report.pdf", strings.NewReader("x"), WithFileDealID(0)); err == nil {
		t.Fatalf("expected invalid deal id error")
	}
	if _, err := client.Files.Upload(context.Background(), "report.pdf", strings.NewReader("x"), WithFileLeadID("")); err == nil {
		t.Fatalf("expected invalid lead id error")
	}
}

