// http.NewRequestWithContext only provides GetBody for *bytes.Buffer,
// *bytes.Reader and *strings.Reader. Without GetBody the retry transport
// cannot replay the body, so retryable responses (e.g. 429) surface as
// errors. Seekable bodies such as files opened with os.Open can be
// rewound, so install a GetBody that seeks back to the starting offset.
if req.GetBody == nil {
	if seeker, ok := reqBody.(io.ReadSeeker); ok {
		start, err := seeker.Seek(0, io.SeekCurrent)
		if err != nil {
			return fmt.Errorf("determine body offset: %w", err)
		}
		req.GetBody = func() (io.ReadCloser, error) {
			if _, err := seeker.Seek(start, io.SeekStart); err != nil {
				return nil, err
			}
			return io.NopCloser(seeker), nil
		}
	}
}

