	cfg := newFilesUploadOptions([]FilesUploadOption{
		nil,
		WithFileDealID(1),
		WithFilePersonID(2),
		WithFileOrganizationID(3),
		WithFileProductID(4),
		WithFileActivityID(5),
		WithFileLeadID("lead-id"),
		WithFileProjectID(6),
		WithFilesRequestOptions(pipedrive.WithHeader("X-Test", "1")),
	})

	if cfg.dealID == nil || *cfg.dealID != 1 {
		t.Fatalf("unexpected deal id: %#v", cfg.dealID)
	}
	if cfg.personID == nil || *cfg.personID != 2 {
		t.Fatalf("unexpected person id: %#v", cfg.personID)
	}
	if cfg.orgID == nil || *cfg.orgID != 3 {
		t.Fatalf("unexpected organization id: %#v", cfg.orgID)
	}
	if cfg.productID == nil || *cfg.productID != 4 {
		t.Fatalf("unexpected product id: %#v", cfg.productID)
	}
	if cfg.activityID == nil || *cfg.activityID != 5 {
		t.Fatalf("unexpected activity id: %#v", cfg.activityID)
	}
	if cfg.leadID == nil || *cfg.leadID != "lead-id" {
		t.Fatalf("unexpected lead id: %#v", cfg.leadID)
	}
	if cfg.projectID == nil || *cfg.projectID != 6 {
		t.Fatalf("unexpected project id: %#v", cfg.projectID)
